public class Store {
    public static void main(String[] args) {
        int pointBalance = 1000;   // 보유 포인트
        int potionPrice = 300;     // 물약 가격
        int bought = 0;

        for (int i = 0; i < 5; i++) {          // 최대 5개까지 시도
            if (pointBalance >= potionPrice) { // 살 수 있으면
                pointBalance -= potionPrice;   // 잔액 차감
                bought++;
            }
        }
        System.out.println("구매: " + bought + "개, 잔액: " + pointBalance);
    }
}

class Item {                 // 아이템 설계도
