}

Item potion = new Item();    // 객체 생성
potion.name = "체력 물약";
potion.price = 300;

Wallet wallet = new Wallet();
wallet.balance = 1000;

if (wallet.balance >= potion.price) {
    wallet.balance -= potion.price;
}
System.out.println(potion.name + " 구매 후 잔액: " + wallet.balance);

class Wallet {
    private int balance;                 // 밖에서 직접 못 바꿈

    Wallet(int balance) { this.balance = balance; }
    void earn(int amount) { balance += amount; }   // 적립
    void spend(int amount) { balance -= amount; }  // 차감
    int getBalance() { return balance; }
}

Wallet wallet = new Wallet(1000);
wallet.earn(500);            // 이벤트 보상 적립
wallet.spend(potion.price);  // 물약 구매 차감
System.out.println("잔액: " + wallet.getBalance());

// Item에 생성자 추가: Item(String name, int price)
List<Item> shop = new ArrayList<>();
shop.add(new Item("체력 물약", 300));
shop.add(new Item("공격 부스터", 500));

Map<String, Integer> inventory = new HashMap<>();
for (Item item : shop) {                        // 진열대를 훑기
    if (wallet.getBalance() >= item.price) {
        wallet.spend(item.price);
        inventory.merge(item.name, 1, Integer::sum); // 보유 +1
    }
}
System.out.println("보유 아이템: " + inventory);

class NotEnoughPointException extends RuntimeException {
    NotEnoughPointException(String msg) { super(msg); }
}

// Wallet.spend 개선: 차감 전에 검사
void spend(int amount) {
    if (amount > balance) {
        throw new NotEnoughPointException(
            "포인트 부족: 필요 " + amount + ", 보유 " + balance);
    }
    balance -= amount;
}

try {
    wallet.spend(9999);      // 잔액보다 큰 구매 시도
} catch (NotEnoughPointException e) {
    System.out.println("구매 실패 - " + e.getMessage());
}

