public void usePoint(int amount) {
    if (this.point < amount)
        throw new IllegalStateException("포인트 부족");
    this.point -= amount;
}

@Service
@RequiredArgsConstructor
public class OrderService {
    private final EntityManager em;

    @Transactional
    public Long purchaseItem(Long memberId, int amount) {
        Member member = em.find(Member.class, memberId);
        member.usePoint(amount);          // ① 포인트 차감
        Order order = new Order(member, amount);
        em.persist(order);                // ② 주문 생성
        return order.getId();
    }   // ①·② 사이에서 예외가 나면 둘 다 롤백
}

public interface MemberRepository
        extends JpaRepository<Member, Long> { }

public interface OrderRepository
        extends JpaRepository<Order, Long> {
    List<Order> findByMemberIdOrderByIdDesc(Long memberId);   // 주문 내역
}

public interface EventParticipationRepository
