@ExtendWith(MockitoExtension.class)
class PointPaymentServiceTest {

    @Mock PointRepository pointRepository;   // 협력 객체를 가짜로
    @Mock PaymentGateway paymentGateway;
    @InjectMocks PointPaymentService service;

    @Test
    void 잔액을_읽어_결제하고_게이트웨이를_올바른_금액으로_부른다() {
        // given: 스텁으로 상황 고정
        given(pointRepository.findBalance("player1")).willReturn(5000);
        var item = new Item("전설의_검", 3000);

        // when
        service.purchase("player1", item);

        // then: 협력 객체가 기대대로 불렸는지 검증
        then(paymentGateway).should().charge("player1", 3000);
        then(pointRepository).should().save("player1", 2000);
    }
}

