  const res = await fetch("http://localhost:8080/api/events");
  return res.json();   // GameEvent[] 로 타입 보장
}

export default async function EventListPage() {
  const events = await getEvents();
  return (
    <ul>
      {events
        .filter((e) => e.status === "ONGOING")
        .map((e) => (
          <li key={e.eventId}>{e.title}</li>
        ))}
    </ul>
  );
}

// app/items/[itemId]/BuyButton.tsx (클라이언트 컴포넌트)
"use client";
import { useState } from "react";

export default function BuyButton({ itemId }: { itemId: number }) {
  const [msg, setMsg] = useState("");

  async function buy() {
    const res = await fetch("http://localhost:8080/api/purchases", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ itemId }),
    });
    if (res.ok) setMsg("구매 완료!");
    else if (res.status === 402) setMsg("포인트가 부족합니다");
  }

  return <button onClick={buy}>구매 {msg && `— ${msg}`}</button>;
}
